using TdLib.TdApi;
using TdLib.TdApi.Objects;
namespace TdLib.Api.OpenTelemetry;
/// <summary>
/// Autogenerated TDLib APIs
/// </summary>

public partial class ClientOpenTelemetryDecorator
{
    /// <summary>
    /// Changes the list of emojis corresponding to a sticker. The sticker must belong to a regular or custom emoji sticker set that is owned by the current user
    /// </summary>
    public Task<TdLib.TdApi.Objects.Ok> SetStickerEmojisAsync(InputFile sticker = default, string emojis = default)
    {

           using var activity =  StartCallActivity("SetStickerEmojisAsync", typeof(SetStickerEmojis).FullName ?? "SetStickerEmojisAsync");

           try
           {
             return client.SetStickerEmojisAsync(sticker, emojis);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
